export function getDistrictsForState(stateNameOrId: string): DistrictMaster[] {
  const query = stateNameOrId.trim().toLowerCase();
  return MASTER_DISTRICTS.filter(
    d => d.state_name.toLowerCase() === query || d.state_id.toLowerCase() === query
  ).sort((a, b) => a.district_name.localeCompare(b.district_name));
}

export function findDistrictByName(districtName: string, stateName?: string): DistrictMaster | undefined {
  const dQuery = districtName.trim().toLowerCase();
  if (stateName) {
    const sQuery = stateName.trim().toLowerCase();
    return MASTER_DISTRICTS.find(
      d => d.district_name.toLowerCase() === dQuery && d.state_name.toLowerCase() === sQuery
    );
  }
  return MASTER_DISTRICTS.find(d => d.district_name.toLowerCase() === dQuery);
}
